from fastapi import FastAPI

app = FastAPI()

@app.get("/")
def read_root():
    return {"message": "Hello World"}

@app.get("/items/{item_id}", summary="Read one item",
         description="Returns a single item by its ID.", tags=["items"])
def read_item(item_id: int):
    return {"item_id": item_id}
